  Definition loop_res (R : bvmap 5 word) (pc : Z) : Prop :=
    exists R', (exists r, efound r /\ msteps ASEGS (st R pc M) (st R' E_FOUND M) /\ aonlyT R R' /\ getr R' 10%bv = Z_to_bv 64 r)
               \/ (msteps ASEGS (st R pc M) (st R' E_NF M) /\ aonlyT R R').

