  Lemma emp_from_bb : forall R (pw : Z), SENV -> bc <> 0 ->
    getr R 8%bv = Z_to_bv 64 obj -> getr R 20%bv = Z_to_bv 64 SHBASE -> getr R 22%bv = Z_to_bv 64 key ->
    getr R 23%bv = Z_to_bv 64 (obj / 8) -> getr R 24%bv = Z_to_bv 64 bc -> getr R 27%bv = Z_to_bv 64 (hmod key bc) ->
    getr R 11%bv = Z_to_bv 64 pw -> 0 <= pw < 2 ^ 64 -> (bc <> 2 -> 2 <= pw) -> (bc = 2 -> pw < 2) ->
